SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='af51698d-d972-577c-93e6-d73d49691233'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('834fc7af-dc6c-5d9a-977b-c8d3bcb9c42b','0e3a16e4-ffe7-5838-9d35-f7de8c2abca6')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='af51698d-d972-577c-93e6-d73d49691233'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='af51698d-d972-577c-93e6-d73d49691233'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('834fc7af-dc6c-5d9a-977b-c8d3bcb9c42b','0e3a16e4-ffe7-5838-9d35-f7de8c2abca6')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='af51698d-d972-577c-93e6-d73d49691233'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
