  AND q.subject_scope='CustomerProfile:'||c.id::text AND q.semantic_key='customer-controls-customer-08-wrong-history-actor' AND q.fingerprint='af5c10939f453d392d89096b71a8148ec89f6a42b77db093e947ca8a7723b203'
  AND q.state='committed' AND q.source_revision=0 AND q.result_schema_id='SH-004.v1#/$defs/response' AND q.result_schema_version='1'
  AND q.result_body='{"contract":"SH-004.v1","requestId":"customer-08-wrong-history-actor","status":"ok","value":{"customerProfileId":"af51698d-d972-577c-93e6-d73d49691233","userId":"5a98ebb4-db01-56b6-a881-47c1daa72bc3","lifecycle":"active","sourceToken":"0","receipt":{"owner":"customer_buyer_profile","id":"834fc7af-dc6c-5d9a-977b-c8d3bcb9c42b","semanticKey":"customer-controls-customer-08-wrong-history-actor","fingerprint":"af5c10939f453d392d89096b71a8148ec89f6a42b77db093e947ca8a7723b203","sourceToken":"0","recordedAt":"2026-11-17T00:00:00Z"}}}'::jsonb AND q.result_digest=encode(sha256(convert_to(q.result_body::text,'UTF8')),'hex')
 JOIN app.customer_profile_lifecycle_event h ON h.id='7ec5676b-a108-5f4c-8b2c-51ff1097744a' AND h.customer_profile_id=c.id AND h.command_receipt_id=q.id
  AND h.source_revision=0 AND h.from_status IS NULL AND h.to_status=c.status AND h.actor_user_id=c.user_id AND h.name='customer.lifecycle_changed.v1'
 JOIN platform.owner_mutation_evidence e ON e.id='3676c3b8-3b6d-5481-a4ca-99fa9564d52b' AND e.command_receipt_id=q.id AND e.owner_module_id=q.owner_module_id
  AND e.aggregate_kind='CustomerProfile' AND e.aggregate_id=c.id::text AND e.previous_revision IS NULL AND e.committed_revision=0
  AND e.action=q.operation AND e.decision_ref='customer-controls-v1' AND e.evidence_schema_version='1'
  AND e.evidence_schema_id='urn:workinants:database-review:owner-evidence:v1#/$defs/CustomerProfile'
  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"af51698d-d972-577c-93e6-d73d49691233"},"prior":null,"committed":{"id":"af51698d-d972-577c-93e6-d73d49691233","userId":"5a98ebb4-db01-56b6-a881-47c1daa72bc3","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='af51698d-d972-577c-93e6-d73d49691233' AND c.user_id='5a98ebb4-db01-56b6-a881-47c1daa72bc3' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
  AND c.display_name IS NULL AND c.avatar_media_id IS NULL AND c.city IS NULL AND c.state IS NULL AND c.country IS NULL AND c.archived_at IS NULL
