  AND (SELECT count(*) FROM platform.runtime_outbox_message o WHERE o.command_receipt_id=q.id AND o.producer_owner=q.owner_module_id
   AND o.aggregate_kind='CustomerProfile' AND o.aggregate_id=c.id::text AND o.source_revision=0 AND o.source_generation=0 AND o.schema_version='1'
   AND o.causation_id=q.id::text AND o.correlation_id='customer-08-wrong-history-actor' AND o.mutation_transaction_id=c.mutation_transaction_id
   AND o.payload_hash=encode(sha256(convert_to(o.payload::text,'UTF8')),'hex')
   AND ((o.id='3a6206b1-0516-5f39-8dbb-fec503a89c5d' AND o.ordinal=0 AND o.kind='event' AND o.name='customer.lifecycle_changed.v1'
    AND o.payload_schema_id='urn:workin-ants:types:v1#/$defs/EventPayload_customer_lifecycle_changed_v1' AND o.payload='{"eventName":"customer.lifecycle_changed.v1","customerProfileId":"af51698d-d972-577c-93e6-d73d49691233","userId":"5a98ebb4-db01-56b6-a881-47c1daa72bc3","lifecycleRevision":"0","safeState":"active"}'::jsonb)
    OR (o.id='757fbb44-a0d6-56c6-a1b5-91ef40d1dd86' AND o.ordinal=1 AND o.kind='command' AND o.name='assignDefaultFreeTrack.v1'
    AND o.payload_schema_id='urn:workinants:database-review:foundation-payloads:v1#/$defs/assignDefaultFreeTrackCustomerCommand' AND o.payload='{"sourceOwner":"customer_buyer_profile","userId":"5a98ebb4-db01-56b6-a881-47c1daa72bc3","track":"customer","customerProfileId":"af51698d-d972-577c-93e6-d73d49691233","sourceCreationRevision":"0","sourceCreationReceipt":"834fc7af-dc6c-5d9a-977b-c8d3bcb9c42b","semanticKey":"customer_buyer_profile/af51698d-d972-577c-93e6-d73d49691233/default-free-enrollment/v1"}'::jsonb)))=2));
